// §19 WF02 — คำนวณคะแนนความสนใจจากพฤติกรรม (กติกาเดียวกับแผนหมวด 4)
const body = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const prospectId = body.prospectId || body.prospect_id || body.visitorId || null;
const events = Array.isArray(body.events) ? body.events : [];
const W = { page_view: 5, scroll_depth: 3, video_view: 12, video_complete: 18, form_submit: 20,
  callback_request: 30, topic_select: 10, email_open: 8, email_click: 14, reply: 25, appointment: 40, share: 8 };
const breakdown = {};
let topicPoints = 0;
const topics = [];
for (const e of events) {
  const t = String(e.type || e.event || e.name || '').toLowerCase();
  const hits = Math.max(1, Math.min(20, Number(e.count || 1)));
  const w = W[t] || 0;
  if (!w) continue;
  breakdown[t] = (breakdown[t] || 0) + w * hits;
  if (t === 'topic_select') { topicPoints += w * hits; }
  if (e.topic) topics.push({ topic: String(e.topic).slice(0, 80), weight: Math.min(100, w * 5) });
}
if (topicPoints > 30) breakdown.topic_cap = 30 - topicPoints;   // เพดาน +30 ต่อรอบ
let ruleScore = 0;
for (const k of Object.keys(breakdown)) ruleScore += breakdown[k];
ruleScore = Math.max(0, Math.round(ruleScore));
const level = ruleScore >= 70 ? 'HIGH_INTENT' : ruleScore >= 40 ? 'INTERESTED' : ruleScore >= 20 ? 'WARM' : 'LOW';
return [{ json: { prospectId, events: events.length, breakdown, topics,
  ruleScore, level, source: body.source || 'n8n-pi-02', consentMarketing: !!(body.consent && body.consent.marketing),
  name: body.name || null, channel: body.channel || null } }];

// รวมคะแนนกติกา + ข้อวิเคราะห์จาก AI
const rule = $('คำนวณคะแนนจากพฤติกรรม').first().json;
const out = ($json && typeof $json.output === 'string') ? $json.output : '';
let ai = {};
try {
  const m = out.match(/\{[\s\S]*\}/);
  ai = m ? JSON.parse(m[0]) : {};
} catch (e) { ai = {}; }
const aiTopics = Array.isArray(ai.topics) ? ai.topics.slice(0, 6).map(t => ({
  topic: String(t.topic || t.name || t).slice(0, 80),
  weight: Math.max(0, Math.min(100, Number(t.weight || 50))),
})) : [];
const topics = aiTopics.length ? aiTopics : rule.topics.slice(0, 6);
const boost = Math.max(0, Math.min(15, Number(ai.scoreBoost || 0)));
const score = Math.max(0, Math.round(rule.ruleScore + boost));
const level = score >= 70 ? 'HIGH_INTENT' : score >= 40 ? 'INTERESTED' : score >= 20 ? 'WARM' : 'LOW';
return [{ json: { prospectId: rule.prospectId, score, level, scoreMode: 'set', breakdown: rule.breakdown, topics,
  aiOk: !!out, aiSummary: String(ai.summary || out).slice(0, 400),
  aiSuggestedAction: String(ai.suggestedAction || ai.action || '').slice(0, 200),
  hot: score >= 70, name: rule.name, channel: rule.channel } }];
